  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\n// Looking for ways to speed up your queries, or scale easily with your serverless or edge functions?\n// Try Prisma Accelerate: https://pris.ly/cli/accelerate-init\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// Purpose: Links messages and conversations to your WhatsApp Business account’s phone number.\n// Why Needed: The API’s webhook includes metadata.phone_number_id to identify which phone number received/sent a message.\n// Notes: Use phone_number_id from the webhook’s metadata as the id. Supports multiple numbers if your app scales.\n\nmodel PhoneNumbers {\n  id                 String          @id // Primary key (WhatsApp phone_number_id from API metadata)\n  displayPhoneNumber String          @unique // e.g., \"15551234567\"\n  createdAt          DateTime        @default(now())\n  updatedAt          DateTime        @updatedAt\n  conversations      Conversations[]\n  messages           Messages[]\n}\n\n// Purpose: Tracks users for chat lists and message attribution.\n// Why Needed: Webhook payloads include contacts with wa_id (phone number) and profile.name. This table maps wa_id to display names.\n// Notes: profileName is nullable since not all contacts provide a name. Update it when new webhook data arrives.\n\nmodel Contacts {\n  waId          String          @id // Primary key (WhatsApp ID, e.g., phone number \"1234567890\")\n  profileName   String? // Contact’s name from webhook (contacts.profile.name)\n  createdAt     DateTime        @default(now())\n  updatedAt     DateTime        @updatedAt\n  conversations Conversations[]\n  messages      Messages[]\n}\n\n// Purpose: Represents a chat thread with a contact, shown in the interface’s sidebar.\n// Why Needed: Simplifies fetching recent chats and their latest messages (like WhatsApp’s chat list).\n// Notes: lastMessageId and lastMessageAt are updated whenever a new message arrives to keep the chat list ordered.\n\nmodel Conversations {\n  id            String       @id @default(uuid())\n  phoneNumberId String\n  contactWaId   String\n  lastMessageId String?\n  lastMessageAt DateTime?\n  createdAt     DateTime     @default(now())\n  updatedAt     DateTime     @updatedAt\n  phoneNumber   PhoneNumbers @relation(fields: [phoneNumberId], references: [id])\n  contact       Contacts     @relation(fields: [contactWaId], references: [waId])\n  messages      Messages[]   @relation(\"ConversationMessages\")\n  lastMessage   Messages?    @relation(\"ConversationLastMessage\", fields: [lastMessageId], references: [id])\n  Messages      Messages[]\n\n  @@unique([phoneNumberId, contactWaId]) // One conversation per contact per phone number\n}\n\n// Purpose: Stores all message details for rendering chat history.\n// Why Needed: Captures webhook data (messages and statuses) and supports the interface’s conversation view.\n// Notes:\n// id uses the webhook’s messages.id (e.g., \"wamid.xxx\") for uniqueness.\n// type maps to webhook’s type (e.g., \"text\", \"image\").\n// textBody, mediaId, etc., are nullable to store only relevant data per type.\n// isFromUs distinguishes sent vs. received messages for UI (e.g., right vs. left bubbles).\n// status is updated via webhook statuses (sent, delivered, read, failed).\n// mediaUrl is optional if you download media to your server (recommended for performance).\n\nmodel Messages {\n  id             String        @id\n  conversationId String\n  phoneNumberId  String\n  contactWaId    String\n  type           String\n  textBody       String?\n  mediaId        String?\n  mediaMimeType  String?\n  mediaUrl       String?\n  caption        String?\n  location       Json?\n  isFromUs       Boolean\n  status         String\n  timestamp      DateTime\n  createdAt      DateTime      @default(now())\n  updatedAt      DateTime      @updatedAt\n  conversation   Conversations @relation(fields: [conversationId], references: [id])\n  phoneNumber    PhoneNumbers  @relation(fields: [phoneNumberId], references: [id])\n  contact        Contacts      @relation(fields: [contactWaId], references: [waId])\n\n  Conversations Conversations[] @relation(\"ConversationMessages\")\n\n  ConversationsLastMessage Conversations[] @relation(\"ConversationLastMessage\")\n}\n",
